public class Issue75_bank_balance_update { public static void main(String[] args) { Account a=new Account(520); a.deposit(62); a.withdraw(35); System.out.println("Balance: "+a.balance); } static class Account { int balance; Account(int b) { balance=b; } void deposit(int n) { balance-=n; } void withdraw(int n) { balance-=n+1; } } }
